const {capture}=require('./workspaces/extractor-srs-design/runtime/capture-and-parse.js');
const {tablesFromHtml,LIMITS}=require('./workspaces/extractor-srs-design/runtime/html-response-parser.js');
(async()=>{
const c=await capture('https://chatgpt.com/share/6ae9dd85-7ff0-83e8-90c3-4592305a2362');
const tbl=tablesFromHtml(c.html.toString('utf8'),LIMITS).tables[0];
const target=tbl.findIndex(x=>Array.isArray(x)&&x[0]==='P');
const ownerRefs=[];
for(let i=0;i<tbl.length;i++){
 const x=tbl[i];
 if(Array.isArray(x)){
   if(x[0]==='P'||x[0]==='D')continue;
   for(let j=0;j<x.length;j++)if(x[j]===target)ownerRefs.push({parent:i,type:'array',position:j});
 }else if(x&&typeof x==='object'){
   for(const [k,v] of Object.entries(x))if(v===target){
     const key=tbl[Number(k.slice(1))];
     const allow=['loaderData','serverResponse','data','deferred','promise','promises','mapping','linear_conversation','message','content','parts','routes','root','value'];
     ownerRefs.push({parent:i,type:'object',key:allow.includes(key)?key:'[redacted-key]'});
   }
 }
}
const tagged=tbl[target];
const reference=tagged[1];
console.log(JSON.stringify({target,targetValueType:typeof reference,targetValueSlotKind:typeof tbl[reference],targetValueLength:Array.isArray(tbl[reference])?tbl[reference].length:null,owners:ownerRefs.slice(0,12),totalOwners:ownerRefs.length}));
})().catch(e=>{console.log(JSON.stringify({error:e.message}));process.exitCode=1});
